import{_ as a,o as t,c as s,a6 as i}from"./chunks/framework.BJFjZBwW.js";const n="/dev/assets/OpenMQTTGateway_serial3.BsP1E_Yx.jpg",b=JSON.parse('{"title":"Infrared gateway","description":"Unlock the potential of Infrared technology with our universal gateway. Decode signals from various devices, and integrate seamlessly with MQTT systems abd controllers like Home Assistant and OpenHAB.","frontmatter":{"title":"Infrared gateway","description":"Unlock the potential of Infrared technology with our universal gateway. Decode signals from various devices, and integrate seamlessly with MQTT systems abd controllers like Home Assistant and OpenHAB."},"headers":[],"relativePath":"use/ir.md","filePath":"use/ir.md","lastUpdated":1720024798000}'),o={name:"use/ir.md"};function r(l,e,p,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="ir-gateway" tabindex="-1">IR gateway <a class="header-anchor" href="#ir-gateway" aria-label="Permalink to &quot;IR gateway&quot;">​</a></h1><p>There is two methods for finding the IR codes you want to replicate:</p><ol><li>Point the remote control to an IR receiver see <a href="#receiving-data-from-ir-signal">Receiving data from IR signal</a> &amp; <a href="#send-data-by-mqtt-to-convert-it-on-ir-signal">Send data by MQTT to convert it on IR signal</a></li><li>Find the code corresponding to your devices with IR global cache database <a href="https://irdb.globalcache.com/" target="_blank" rel="noreferrer">https://irdb.globalcache.com/</a> see <a href="#send-data-by-mqtt-from-global-caché-database-to-convert-it-on-ir-signal">Send data by MQTT from Global cache database to convert it on IR signal</a></li></ol><p>Here is the <a href="https://docs.google.com/spreadsheets/d/1rTDZIG8rm0dSf4vP7HdTdM4-aRY1nDWH4jK28_WRwHQ/edit?usp=sharing" target="_blank" rel="noreferrer">List of protocols</a> supported by OMG, even if your device brand is not in the list you can still use raw IR data or GlobalCache database.</p><h2 id="receiving-data-from-ir-signal" tabindex="-1">Receiving data from IR signal <a class="header-anchor" href="#receiving-data-from-ir-signal" aria-label="Permalink to &quot;Receiving data from IR signal&quot;">​</a></h2><p>Subscribe to all the messages with mosquitto or open your MQTT client software: <code>mosquitto_sub -t +/# -v</code> And press your IR remote control in front of the receiver led you should see the following messages for example:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">home/OpenMQTTGateway/IRtoMQTT {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">875849879</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocol_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">SAMSUNG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;bits&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;raw&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;4534,4432,612,518,614,516,616,1618,618,1616,618,512,618,1618,608,524,612,518,616,514,618,512,616,1618,616,1618,618,514,616,1618,616,514,616,514,618,512,616,1618,618,1618,618,514,610,1622,616,514,618,514,614,516,616,1618,618,512,618,512,618,1616,550,580,618,1616,612,1624,618,1616,618&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>With an hexadecimal value:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9938405643</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">55</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;bits&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">35</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;hex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0x25060090B&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocol_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TECO&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>To receive big dump of raw data you need first to modify the <a href="https://github.com/1technophile/OpenMQTTGateway/blob/091b317660fd201a30e2cd0e15424a13c5a6bd71/config_IR.h#L41" target="_blank" rel="noreferrer">config_IR.h</a> and uncomment DumpMode true</p><p>Unknown protocols are filtered by default, if you want to see the unknown protocols set into <a href="https://github.com/1technophile/OpenMQTTGateway/blob/master/config_IR.h" target="_blank" rel="noreferrer">config_IR.h</a><code>#define pubIRunknownPrtcl true</code> instead of false</p><p><img src="'+n+`" alt="IR serial"></p><p>You can take this code and try to reproduce it with the gateway either by using <a href="#send-data-by-mqtt-to-convert-it-on-ir-signal">decimal value</a> or the <a href="#send-raw-ir-data-by-mqtt">raw value</a>.</p><h2 id="send-data-by-mqtt-to-convert-it-on-ir-signal" tabindex="-1">Send data by MQTT to convert it on IR signal <a class="header-anchor" href="#send-data-by-mqtt-to-convert-it-on-ir-signal" aria-label="Permalink to &quot;Send data by MQTT to convert it on IR signal&quot;">​</a></h2><p>With the IR gateway you need to put on the topic the protocol_name you want to use to send the signal, the different protocols implemented are <a href="https://github.com/crankyoldgit/IRremoteESP8266/blob/f9d7e5c622670132731e3f9c64d9132128eb320c/src/IRremoteESP8266.h#L299" target="_blank" rel="noreferrer">here</a></p><p>Exhaustive list <a href="https://docs.google.com/spreadsheets/d/1_5fQjAixzRtepkykmL-3uN3G5bLfQ0zMajM9OBZ1bx0/edit#gid=1910001295" target="_blank" rel="noreferrer">here</a></p><p>For example if I want to send a command to a Sony TV you can use the following command:</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoIR -m &#39;{&quot;value&quot;:551489775,&quot;protocol_name&quot;:&quot;SONY&quot;}&#39;</code></p><p>The code after the -m represent the payload you want to send.</p><p>You could alternatively use an hex value (bits is the number of hexadecimal values): <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoIR -m &#39;{&quot;hex&quot;:&quot;0x250600090B&quot;,&quot;bits&quot;:5,&quot;protocol_name&quot;:&quot;TECO&quot;}&#39;</code></p><p>or</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoIR -m &#39;{&quot;hex&quot;:&quot;0xA6BCF20040600020000000000519&quot;,&quot;bits&quot;:14,&quot;protocol_name&quot;:&quot;HAIER_AC_YRW02&quot;}&#39;</code></p><p>If you don’t want to use special parameters for IR just use value key, the protocol per default is NEC</p><p><code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoIR -m &#39;{&quot;value&quot;:551489775}&#39;</code></p><p>NOTE: on Arduino Uno most of the protocols are not enable per default due to memory constraints (it is not the case for MEGA), to enable them go to <a href="https://github.com/1technophile/OpenMQTTGateway/blob/master/main/User_config.h" target="_blank" rel="noreferrer">User_config.h</a> and uncomment the #define corresponding the protocols you want:</p><div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//#define IR_COOLIX</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//#define IR_Whynter</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//#define IR_LG</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//#define IR_Sony</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//#define IR_DISH</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//#define IR_RC5</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//#define IR_Sharp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IR_SAMSUNG</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="send-data-by-mqtt-from-global-cache-database-to-convert-it-on-ir-signal" tabindex="-1">Send data by MQTT from Global Caché database to convert it on IR signal <a class="header-anchor" href="#send-data-by-mqtt-from-global-cache-database-to-convert-it-on-ir-signal" aria-label="Permalink to &quot;Send data by MQTT from Global Caché database to convert it on IR signal&quot;">​</a></h2><p>The website <a href="https://irdb.globalcache.com/" target="_blank" rel="noreferrer">https://irdb.globalcache.com/</a> contains an important database of IR codes of various devices brand. By registering and asking the code you will receive a code as the example below:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>code1: sendir,1:1,1,38000,1,69,340,169,20,20,20,20,20,64,20,20,20,20,20,20,20,20,20,20,20,64,20,64,20,20,20,64,20,64,20,64,20,64,20,64,20,64,20,64,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,64,20,64,20,64,20,64,20,64,20,64,20,1544,340,85,20,3663</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Extract this part of the code:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>38000,1,69,340,169,20,20,20,20,20,64,20,20,20,20,20,20,20,20,20,20,20,64,20,64,20,20,20,64,20,64,20,64,20,64,20,64,20,64,20,64,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,20,64,20,64,20,64,20,64,20,64,20,64,20,1544,340,85,20,3663</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>and publish it to MQTT with the subject containing IR_GC:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoIR -m &#39;{&quot;raw&quot;:&quot;38000,1,1,171,171,21,64,21,21,21,21,21,21,21,21,21,21,21,21,21,64,21,64,21,21,21,21,21,21,21,21,21,21,21,21,21,64,21,21,21,21,21,21,21,64,21,21,21,21,21,21,21,21,21,64,21,64,21,64,21,21,21,64,21,64,21,64,21,64,21,1114&quot;,&quot;protocol_name&quot;:&quot;GC&quot;}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>You should be able to command your devices without having listened with the IR receiver or if your protocol is unknown by the IRremote library</p><h2 id="send-data-by-mqtt-with-advanced-ir-parameters" tabindex="-1">Send data by MQTT with advanced IR parameters <a class="header-anchor" href="#send-data-by-mqtt-with-advanced-ir-parameters" aria-label="Permalink to &quot;Send data by MQTT with advanced IR parameters&quot;">​</a></h2><p>IR sending support two advanced parameters; bits length and repeat number.</p><p>The example below will send the following advanced parameters bits: 14 and repeat:4 times for a Sony protocol:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoIR -m &#39;{&quot;value&quot;:551489775,&quot;protocol_name&quot;:&quot;NEC&quot;,&quot;repeat&quot;:4,&quot;bits&quot;:14}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="send-raw-ir-data-by-mqtt" tabindex="-1">Send raw IR data by MQTT <a class="header-anchor" href="#send-raw-ir-data-by-mqtt" aria-label="Permalink to &quot;Send raw IR data by MQTT&quot;">​</a></h2><p>Publish your code like below</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoIR -m &#39;{&quot;raw&quot;:&quot;8850,4450,600,550,550,550,600,1600,600,550,600,500,600,500,600,550,600,500,600,1650,600,1600,600,550,600,1600,600,1650,600,1600,600,1650,600,1600,600,550,600,500,600,550,550,1650,600,500,600,550,600,500,600,550,550,1650,600,1650,550,1650,600,550,550,1650,600,1650,550,1650,600,1650,600&quot;,&quot;protocol_name&quot;:&quot;Raw&quot;}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>With big raw array you may cross the limit of default payload size. In this case the gateway will not receive the message or will not send it to the broker. In this case the best way is to use hex values instead, but if you can&#39;t you may change the parameters below: In User_config.h replace:</p><div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"># define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> JSON_MSG_BUFFER</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 512</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>by</p><div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"># define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> JSON_MSG_BUFFER</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1280</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="repeat-the-ir-signal-openmqttgateway-receive" tabindex="-1">Repeat the IR signal OpenMQTTGateway receive <a class="header-anchor" href="#repeat-the-ir-signal-openmqttgateway-receive" aria-label="Permalink to &quot;Repeat the IR signal OpenMQTTGateway receive&quot;">​</a></h2><p>So as to repeat the IR signal received by the gateway once set the following parameter to true in <a href="https://github.com/1technophile/OpenMQTTGateway/blob/091b317660fd201a30e2cd0e15424a13c5a6bd71/config_IR.h#L37" target="_blank" rel="noreferrer">config_IR.h</a><code>#define repeatIRwMQTT true</code></p><h2 id="raw-ir-signal-forwarding" tabindex="-1">Raw IR signal forwarding <a class="header-anchor" href="#raw-ir-signal-forwarding" aria-label="Permalink to &quot;Raw IR signal forwarding&quot;">​</a></h2><p>So as to repeat the raw IR signal received by the gateway, uncomment and set the following parameter to true in <a href="https://github.com/1technophile/OpenMQTTGateway/blob/091b317660fd201a30e2cd0e15424a13c5a6bd71/config_IR.h#L39" target="_blank" rel="noreferrer">config_IR.h</a><code>#define RawDirectForward true</code></p>`,49)])])}const g=a(o,[["render",r]]);export{b as __pageData,g as default};
